#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/simple-calculator-app-323487-323496/calculator_frontend"
mkdir -p "$WORKSPACE" && cd "$WORKSPACE"
# Package manifest
cat >Package.swift <<'SWIFT'
// swift-tools-version:5.9
import PackageDescription
let package = Package(
  name: "CalculatorPackage",
  products: [ .library(name: "Calculator", targets: ["Calculator"]), .executable(name: "calc-demo", targets: ["CalcDemo"]) ],
  targets: [ .target(name: "Calculator", path: "Sources/Calculator"), .executableTarget(name: "CalcDemo", dependencies: ["Calculator"], path: "Sources/CalcDemo"), .testTarget(name: "CalculatorTests", dependencies: ["Calculator"], path: "Tests/CalculatorTests") ]
)
SWIFT
mkdir -p Sources/Calculator Sources/CalcDemo Tests/CalculatorTests .init
# Library
cat >Sources/Calculator/Calculator.swift <<'SW'
public struct Calculator {
  public init() {}
  public func add(_ a: Int, _ b: Int) -> Int { a + b }
  public func sub(_ a: Int, _ b: Int) -> Int { a - b }
  public func mul(_ a: Int, _ b: Int) -> Int { a * b }
  public func div(_ a: Int, _ b: Int) -> Int { a / b }
}
SW
# Long-running executable (writes pid file for validation)
cat >Sources/CalcDemo/main.swift <<'SW'
import Foundation
import Calculator
let pidPath = FileManager.default.currentDirectoryPath + "/.init/demo.pid"
FileManager.default.createFile(atPath: pidPath, contents: String(ProcessInfo.processInfo.processIdentifier).data(using: .utf8), attributes: nil)
// keep running
while true { sleep(3600) }
SW
# Tests
cat >Tests/CalculatorTests/CalculatorTests.swift <<'SW'
import XCTest
@testable import Calculator
final class CalculatorTests: XCTestCase {
  func testAdd() { XCTAssertEqual(Calculator().add(2,3), 5) }
  func testSub() { XCTAssertEqual(Calculator().sub(5,3), 2) }
}
SW
# start helper: launch built executable
cat >.init/start_demo.sh <<'SH'
#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
PROJECT_ROOT=$(cd "$SCRIPT_DIR"/.. && pwd)
cd "$PROJECT_ROOT"
EXEC=".build/debug/calc-demo"
[ -x "$EXEC" ] || { echo "ERROR: exec not found at $EXEC; run swift build" >&2; exit 2; }
"$EXEC" &
PID=$!
echo "$PID" > "$SCRIPT_DIR/demo.pid"
SH
chmod +x .init/start_demo.sh
# stop helper
cat >.init/stop_demo.sh <<'SH'
#!/usr/bin/env bash
set -euo pipefail
PID_FILE="$(cd "$(dirname "$0")" && pwd)/demo.pid"
[ -f "$PID_FILE" ] || exit 0
PID=$(cat "$PID_FILE")
kill "$PID" || true
sleep 1
rm -f "$PID_FILE"
SH
chmod +x .init/stop_demo.sh
echo "scaffold created"

#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/simple-calculator-app-323487-323496/calculator_frontend"
cd "$WORKSPACE"
command -v swift >/dev/null 2>&1 || { echo "ERROR: swift not found; run install" >&2; exit 2; }
[ -f Package.swift ] || { echo "ERROR: Package.swift missing; run scaffold" >&2; exit 3; }
swift test --parallel
